## Code Example

```javascript
async function processAudioChunk(chunk, tenantId) {
  const text = await asrOnDevice(chunk, tenantId);
  const redacted = await redactPII(text, tenantId);
  const signal = await applyDifferentialPrivacy(redacted, tenantId);

  if (signal.riskScore > config.threshold) {
    await routeToTriageQueue(signal, tenantId);
  }
  return signal;
}
